  ('diseno-grafico', 'Diseño Gráfico', 'Arte y diseño', '#E0567A', 'Domina los fundamentos visuales, la tipografía, el color y las herramientas profesionales para crear piezas de marca, digitales e impresas.', 89900, 5, '[{"title": "Pautas de Accesibilidad para el Contenido Web (WCAG 2)", "publisher": "W3C – Web Accessibility Initiative", "url": "https://www.w3.org/WAI/standards-guidelines/wcag/es", "use": "Accesibilidad visual y diseño UX/UI"}, {"title": "Material Design 3", "publisher": "Google", "url": "https://m3.material.io/", "use": "Sistemas de diseño, componentes y color"}, {"title": "Fonts Knowledge", "publisher": "Google Fonts", "url": "https://fonts.google.com/knowledge", "use": "Tipografía y legibilidad"}, {"title": "Dirección Nacional de Derecho de Autor", "publisher": "Gobierno de Colombia", "url": "https://www.derechodeautor.gov.co/", "use": "Derechos de autor y registro de obras"}]'::jsonb, null),
  ('programacion-de-software', 'Programación de Software', 'Tecnología', '#4F6BED', 'Aprende a programar desde cero: lógica, Python, estructuras de datos, programación orientada a objetos, web y buenas prácticas profesionales.', 89900, 5, '[{"title": "El tutorial de Python", "publisher": "Python Software Foundation", "url": "https://docs.python.org/es/3/tutorial/", "use": "Programación con Python"}, {"title": "Aprende desarrollo web", "publisher": "MDN Web Docs (Mozilla)", "url": "https://developer.mozilla.org/es/docs/Learn_web_development", "use": "HTML, CSS y JavaScript"}, {"title": "Documentación de React", "publisher": "React (Meta)", "url": "https://es.react.dev/learn", "use": "Desarrollo frontend con React"}, {"title": "OWASP Top 10", "publisher": "OWASP Foundation", "url": "https://owasp.org/www-project-top-ten/", "use": "Desarrollo seguro"}, {"title": "Pro Git (libro en español)", "publisher": "Git", "url": "https://git-scm.com/book/es/v2", "use": "Control de versiones"}]'::jsonb, null),
  ('ingenieria-de-sistemas', 'Ingeniería de Sistemas', 'Tecnología', '#2E8BC0', 'Comprende cómo se diseñan, construyen y gestionan sistemas de información: arquitectura, redes, bases de datos, seguridad y gestión de proyectos.', 89900, 5, '[{"title": "Tutorial de PostgreSQL", "publisher": "PostgreSQL Global Development Group", "url": "https://www.postgresql.org/docs/current/tutorial.html", "use": "Bases de datos y SQL"}, {"title": "Cybersecurity Framework", "publisher": "NIST (Estados Unidos)", "url": "https://www.nist.gov/cyberframework", "use": "Ciberseguridad aplicada"}, {"title": "Ley 1273 de 2009 (delitos informáticos)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1273_2009.html", "use": "Marco legal de la seguridad informática"}, {"title": "La Guía de Scrum", "publisher": "Scrum Guides", "url": "https://scrumguides.org/", "use": "Metodologías ágiles"}]'::jsonb, null),
  ('inteligencia-artificial', 'Inteligencia Artificial', 'Tecnología', '#7B5CF0', 'Desde los fundamentos matemáticos hasta el aprendizaje profundo, los modelos de lenguaje y el uso responsable de la IA.', 89900, 5, '[{"title": "CONPES 4144 de 2025: Política Nacional de Inteligencia Artificial", "publisher": "DNP – normograma MinTIC", "url": "https://normograma.mintic.gov.co/mintic/compilacion/docs/conpes_dnp_4144_2025.htm", "use": "IA en Colombia y su regulación"}, {"title": "Recomendación sobre la ética de la inteligencia artificial", "publisher": "UNESCO", "url": "https://www.unesco.org/es/artificial-intelligence/recommendation-ethics", "use": "IA responsable"}, {"title": "Machine Learning Crash Course", "publisher": "Google for Developers", "url": "https://developers.google.com/machine-learning/crash-course?hl=es-419", "use": "Aprendizaje automático"}, {"title": "Guía de usuario de scikit-learn", "publisher": "scikit-learn", "url": "https://scikit-learn.org/stable/user_guide.html", "use": "Modelos de machine learning en Python"}]'::jsonb, null),
  ('derecho', 'Derecho', 'Ciencias sociales', '#8A6D3B', 'Introducción al sistema jurídico colombiano: Constitución, derecho civil, penal, laboral, comercial y nuevas áreas como el derecho digital.', 89900, 5, '[{"title": "Constitución Política de Colombia de 1991", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/constitucion_politica_1991.html", "use": "Derecho constitucional"}, {"title": "Ley 1437 de 2011 (CPACA)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1437_2011.html", "use": "Derecho administrativo"}, {"title": "Código Sustantivo del Trabajo", "publisher": "Cancillería de Colombia (normograma)", "url": "https://cancilleria.gov.co/normograma/compilacion/docs/codigo_sustantivo_trabajo.htm", "use": "Derecho laboral"}, {"title": "Ley 1581 de 2012 (protección de datos personales)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1581_2012.html", "use": "Derecho digital"}, {"title": "Corte Constitucional de Colombia", "publisher": "Rama Judicial", "url": "https://www.corteconstitucional.gov.co/", "use": "Jurisprudencia y tutela"}]'::jsonb, null),
  ('energias-renovables', 'Energías Renovables', 'Ingeniería', '#2BAE66', 'Conoce las fuentes limpias de energía, cómo se diseñan sistemas solares y eólicos y cómo se gestionan proyectos sostenibles en Colombia.', 89900, 5, '[{"title": "Ley 1715 de 2014 (energías renovables no convencionales)", "publisher": "DIAN (normograma)", "url": "https://normograma.dian.gov.co/dian/compilacion/docs/ley_1715_2014.htm", "use": "Marco legal e incentivos"}, {"title": "Ley 2099 de 2021 (transición energética)", "publisher": "DIAN (normograma)", "url": "https://normograma.dian.gov.co/dian/compilacion/docs/ley_2099_2021.htm", "use": "Transición energética en Colombia"}, {"title": "Unidad de Planeación Minero Energética", "publisher": "UPME – Gobierno de Colombia", "url": "https://www.upme.gov.co/", "use": "Planeación y datos de energía"}, {"title": "Agencia Internacional de Energías Renovables", "publisher": "IRENA", "url": "https://www.irena.org/", "use": "Estadísticas y estudios internacionales"}]'::jsonb, null),
