  ('licenciatura-lengua-castellana', 'Licenciatura en Lengua Castellana', 'Educación', '#C0392B', 'Formación en lingüística, gramática, literatura y didáctica para enseñar el español con métodos actuales.', 89900, 5, '[{"title": "Diccionario de la lengua española", "publisher": "RAE – ASALE", "url": "https://dle.rae.es/", "use": "Léxico y norma del español"}, {"title": "Estándares Básicos de Competencias", "publisher": "Ministerio de Educación Nacional", "url": "https://www.mineducacion.gov.co/1621/article-340021.html", "use": "Currículo de lenguaje"}, {"title": "Derechos Básicos de Aprendizaje (DBA) de Lenguaje", "publisher": "Colombia Aprende – MEN", "url": "https://colombiaaprende.edu.co/recurso-coleccion/derechos-basicos-de-aprendizaje-dba-lenguaje", "use": "Planeación de clases"}, {"title": "Instituto Caro y Cuervo", "publisher": "Gobierno de Colombia", "url": "https://www.caroycuervo.gov.co/", "use": "Lingüística y literatura colombiana"}]'::jsonb, null),
  ('educacion-fisica', 'Educación Física', 'Salud y deporte', '#16A085', 'Pedagogía del movimiento, fisiología, deporte y recreación para formar personas activas y saludables.', 89900, 5, '[{"title": "Directrices de la OMS sobre actividad física y hábitos sedentarios", "publisher": "Organización Mundial de la Salud", "url": "https://www.who.int/es/publications/i/item/9789240014886", "use": "Recomendaciones de actividad física por edad"}, {"title": "Documento No. 15: Orientaciones pedagógicas para la educación física, recreación y deporte", "publisher": "Ministerio de Educación Nacional", "url": "https://www.mineducacion.gov.co/1621/article-241887.html", "use": "Didáctica y currículo"}, {"title": "Ley 181 de 1995 (Ley del Deporte)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0181_1995.html", "use": "Sistema Nacional del Deporte"}, {"title": "Ministerio del Deporte", "publisher": "Gobierno de Colombia", "url": "https://www.mindeporte.gov.co/", "use": "Programas y políticas deportivas"}]'::jsonb, null),
