  ('visualizacion-de-datos', 'Visualización de Datos', 'Datos', '#0097A7', 'Convierte datos en historias claras: principios de percepción, tipos de gráficos, dashboards y herramientas como Python, Power BI y D3.', 89900, 5, '[{"title": "Datos Abiertos Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}, {"title": "Documentación de Power BI", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/power-bi/", "use": "Dashboards y BI"}, {"title": "D3", "publisher": "Observable", "url": "https://d3js.org/", "use": "Visualización web interactiva"}, {"title": "Tutoriales de Matplotlib", "publisher": "Matplotlib", "url": "https://matplotlib.org/stable/tutorials/index.html", "use": "Gráficos con Python"}]'::jsonb, null),
  ('big-data', 'Big Data', 'Datos', '#34495E', 'Procesa y analiza grandes volúmenes de datos con arquitecturas distribuidas, Spark, bases NoSQL y pipelines modernos.', 89900, 5, '[{"title": "Documentación de Apache Spark", "publisher": "Apache Software Foundation", "url": "https://spark.apache.org/docs/latest/", "use": "Procesamiento distribuido"}, {"title": "Documentación de Apache Kafka", "publisher": "Apache Software Foundation", "url": "https://kafka.apache.org/documentation/", "use": "Procesamiento en tiempo real"}, {"title": "CONPES 3920 de 2018: Política Nacional de Explotación de Datos (Big Data)", "publisher": "DNP – normograma DIAN", "url": "https://normograma.dian.gov.co/dian/compilacion/docs/conpes_dnp_3920_2018.htm", "use": "Big Data en Colombia"}, {"title": "Ley 1581 de 2012 (protección de datos personales)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1581_2012.html", "use": "Gobierno y privacidad de datos"}]'::jsonb, null),
  ('cloud-computing', 'Cloud Computing', 'Tecnología', '#3A86FF', 'Aprende a desplegar, escalar y asegurar aplicaciones en la nube con AWS, Azure y Google Cloud, contenedores e infraestructura como código.', 89900, 5, '[{"title": "SP 800-145: The NIST Definition of Cloud Computing", "publisher": "NIST (Estados Unidos)", "url": "https://csrc.nist.gov/pubs/sp/800/145/final", "use": "Definición y modelos de la nube"}, {"title": "AWS Well-Architected", "publisher": "Amazon Web Services", "url": "https://aws.amazon.com/es/architecture/well-architected/", "use": "Buenas prácticas de arquitectura"}, {"title": "Documentación de Azure", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/azure/", "use": "Servicios de Microsoft Azure"}, {"title": "Documentación de Google Cloud", "publisher": "Google Cloud", "url": "https://docs.cloud.google.com/docs?hl=es-419", "use": "Servicios de Google Cloud"}, {"title": "Documentación de Kubernetes", "publisher": "Cloud Native Computing Foundation", "url": "https://kubernetes.io/es/docs/home/", "use": "Contenedores y orquestación"}]'::jsonb, null),
  ('administracion-hotelera-y-turistica', 'Administración Hotelera y Turística', 'Negocios', '#B7950B', 'Gestiona hoteles, restaurantes y destinos turísticos con enfoque en servicio, operaciones, revenue management y tecnología.', 89900, 5, '[{"title": "Ley 300 de 1996 (Ley General de Turismo)", "publisher": "Cancillería de Colombia (normograma)", "url": "https://www.cancilleria.gov.co/sites/default/files/Normograma/docs/pdf/ley_0300_1996.pdf", "use": "Marco legal del turismo"}, {"title": "Registro Nacional de Turismo", "publisher": "Confecámaras – MinCIT", "url": "https://rnt.confecamaras.co/", "use": "Registro obligatorio de prestadores turísticos"}, {"title": "Ministerio de Comercio, Industria y Turismo", "publisher": "Gobierno de Colombia", "url": "https://www.mincit.gov.co/minturismo", "use": "Políticas y normas técnicas de turismo"}, {"title": "ONU Turismo", "publisher": "Naciones Unidas", "url": "https://www.untourism.int/es", "use": "Estadísticas y tendencias del turismo mundial"}]'::jsonb, null),
  ('quimica', 'Química', 'Ciencias', '#00A884', 'Estudia la materia y sus transformaciones: átomos, enlaces, reacciones, soluciones, química orgánica y aplicaciones en la industria y el ambiente.', 89900, 5, '[{"title": "Química 2ed (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/qu%C3%ADmica-2ed", "use": "Texto guía del curso"}, {"title": "Tabla periódica de los elementos", "publisher": "IUPAC", "url": "https://iupac.org/what-we-do/periodic-table-of-elements/", "use": "Tabla periódica oficial"}]'::jsonb, null),
  ('biologia', 'Biología', 'Ciencias', '#2E9E44', 'Descubre la vida desde la célula hasta los ecosistemas: genética, evolución, fisiología, biodiversidad colombiana y biotecnología.', 89900, 5, '[{"title": "Conceptos en Biología (OpenStax, en español)", "publisher": "LibreTexts Español", "url": "https://espanol.libretexts.org/Bookshelves/Biologia/Biologia_introductoria_y_general/Libro%3A_Conceptos_en_Biolog%C3%ADa_(OpenStax)", "use": "Texto guía del curso"}, {"title": "Instituto Humboldt", "publisher": "Instituto de Investigación de Recursos Biológicos Alexander von Humboldt", "url": "https://www.humboldt.org.co/", "use": "Biodiversidad de Colombia"}]'::jsonb, null),
  ('matematicas', 'Matemáticas', 'Ciencias', '#5C6BC0', 'Del razonamiento numérico al cálculo y la estadística: álgebra, geometría, funciones, probabilidad y matemáticas aplicadas a la vida y al trabajo.', 89900, 5, '[{"title": "Matemáticas en Khan Academy", "publisher": "Khan Academy", "url": "https://es.khanacademy.org/math", "use": "Ejercicios y videos gratuitos"}, {"title": "Cálculo volumen 1 (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/c%C3%A1lculo-volumen-1", "use": "Cálculo diferencial e integral"}]'::jsonb, null),
  ('astronomia', 'Astronomía', 'Ciencias', '#3949AB', 'Explora el universo: el cielo nocturno, el sistema solar, las estrellas, las galaxias y la cosmología, con observación práctica desde Colombia.', 89900, 5, '[{"title": "NASA Science", "publisher": "NASA", "url": "https://science.nasa.gov/", "use": "Sistema solar, misiones y universo"}, {"title": "Simulaciones PhET", "publisher": "Universidad de Colorado Boulder", "url": "https://phet.colorado.edu/es/", "use": "Simulaciones de gravedad y órbitas"}]'::jsonb, null),
  ('geologia', 'Geología', 'Ciencias', '#8D6E63', 'Comprende la Tierra: minerales, rocas, tectónica de placas, volcanes, sismos, recursos geológicos y amenazas naturales en Colombia.', 89900, 5, '[{"title": "Geología de Colombia (libro)", "publisher": "Servicio Geológico Colombiano", "url": "https://www2.sgc.gov.co/LibroGeologiaColombia/Paginas/Inicio.aspx", "use": "Geología del territorio colombiano"}, {"title": "U.S. Geological Survey", "publisher": "USGS", "url": "https://www.usgs.gov/", "use": "Sismos, volcanes y ciencias de la Tierra"}]'::jsonb, null),
  ('ecologia', 'Ecología', 'Ciencias', '#43A047', 'Aprende cómo se relacionan los seres vivos con su entorno: poblaciones, comunidades, ecosistemas, biodiversidad y restauración ecológica.', 89900, 5, '[{"title": "Instituto Humboldt", "publisher": "Instituto de Investigación de Recursos Biológicos Alexander von Humboldt", "url": "https://www.humboldt.org.co/", "use": "Ecosistemas y biodiversidad de Colombia"}, {"title": "Parques Nacionales Naturales de Colombia", "publisher": "Gobierno de Colombia", "url": "https://www.parquesnacionales.gov.co/", "use": "Áreas protegidas"}]'::jsonb, null),
  ('ciencias-ambientales', 'Ciencias Ambientales', 'Ciencias', '#26A69A', 'Analiza los problemas ambientales y sus soluciones: agua, aire, suelos, residuos, cambio climático, legislación y gestión ambiental en Colombia.', 89900, 5, '[{"title": "IDEAM", "publisher": "Instituto de Hidrología, Meteorología y Estudios Ambientales", "url": "https://www.ideam.gov.co/", "use": "Clima, agua y datos ambientales de Colombia"}, {"title": "Ley 99 de 1993 (Sistema Nacional Ambiental)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0099_1993.html", "use": "Legislación ambiental"}, {"title": "Panel Intergubernamental de Cambio Climático", "publisher": "IPCC – Naciones Unidas", "url": "https://www.ipcc.ch/", "use": "Ciencia del cambio climático"}]'::jsonb, null),
