  ('bioquimica', 'Bioquímica', 'Ciencias', '#C2185B', 'Estudia la química de la vida: biomoléculas, enzimas, metabolismo, bioenergética, señalización celular y aplicaciones en salud y nutrición.', 89900, 5, '[{"title": "PDB-101", "publisher": "RCSB Protein Data Bank", "url": "https://pdb101.rcsb.org/", "use": "Estructura de proteínas y biomoléculas"}, {"title": "KEGG PATHWAY Database", "publisher": "Kanehisa Laboratories", "url": "https://www.genome.jp/kegg/pathway.html", "use": "Rutas metabólicas"}]'::jsonb, null),
  ('ciencias-naturales', 'Ciencias Naturales', 'Ciencias', '#689F38', 'Una visión integrada de la naturaleza: seres vivos, materia, energía, la Tierra y el universo, con experimentos sencillos y enfoque en la escuela.', 89900, 5, '[{"title": "Estándares Básicos de Competencias", "publisher": "Ministerio de Educación Nacional", "url": "https://www.mineducacion.gov.co/1621/article-340021.html", "use": "Currículo de ciencias naturales"}, {"title": "Simulaciones PhET", "publisher": "Universidad de Colorado Boulder", "url": "https://phet.colorado.edu/es/", "use": "Experimentos virtuales"}]'::jsonb, null),
  ('sociologia', 'Sociología', 'Ciencias sociales', '#6A1B9A', 'Comprende cómo funciona la sociedad: instituciones, desigualdad, cultura, cambio social y métodos de investigación aplicados a Colombia.', 89900, 5, '[{"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "Datos sociales de Colombia"}, {"title": "CLACSO", "publisher": "Consejo Latinoamericano de Ciencias Sociales", "url": "https://www.clacso.org/", "use": "Biblioteca y pensamiento social latinoamericano"}]'::jsonb, null),
  ('psicologia', 'Psicología', 'Ciencias sociales', '#8E24AA', 'Estudia la mente y el comportamiento: procesos psicológicos, desarrollo, personalidad, salud mental y campos de aplicación de la psicología.', 89900, 5, '[{"title": "Colegio Colombiano de Psicólogos", "publisher": "Colpsic", "url": "https://www.colpsic.org.co/", "use": "Ejercicio profesional en Colombia"}, {"title": "Ley 1090 de 2006 (ejercicio de la psicología)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1090_2006.html", "use": "Código deontológico y bioético"}, {"title": "American Psychological Association", "publisher": "APA", "url": "https://www.apa.org/", "use": "Investigación y normas APA"}]'::jsonb, null),
  ('antropologia', 'Antropología', 'Ciencias sociales', '#BF360C', 'Estudia la diversidad humana: culturas, pueblos indígenas y afrodescendientes, arqueología, antropología biológica y trabajo etnográfico en Colombia.', 89900, 5, '[{"title": "Instituto Colombiano de Antropología e Historia", "publisher": "ICANH", "url": "https://icanh.gov.co/", "use": "Antropología, arqueología y patrimonio"}, {"title": "CLACSO", "publisher": "Consejo Latinoamericano de Ciencias Sociales", "url": "https://www.clacso.org/", "use": "Pensamiento social latinoamericano"}]'::jsonb, null),
  ('historia', 'Historia', 'Ciencias sociales', '#6D4C41', 'Recorre la historia universal y de Colombia: civilizaciones, conquista, independencia, república, conflicto, memoria y el oficio del historiador.', 89900, 5, '[{"title": "Archivo General de la Nación", "publisher": "Gobierno de Colombia", "url": "https://www.archivogeneral.gov.co/", "use": "Fuentes primarias de la historia de Colombia"}, {"title": "Biblioteca Nacional de Colombia", "publisher": "Ministerio de las Culturas", "url": "https://bibliotecanacional.gov.co/", "use": "Prensa histórica y libros digitalizados"}, {"title": "Informe Final de la Comisión de la Verdad", "publisher": "Comisión de la Verdad", "url": "https://www.comisiondelaverdad.co/", "use": "Memoria del conflicto armado"}]'::jsonb, null),
  ('geografia', 'Geografía', 'Ciencias sociales', '#00897B', 'Comprende el espacio y el territorio: cartografía, geografía física y humana, regiones de Colombia, SIG y ordenamiento territorial.', 89900, 5, '[{"title": "Instituto Geográfico Agustín Codazzi", "publisher": "IGAC", "url": "https://www.igac.gov.co/", "use": "Cartografía oficial de Colombia"}, {"title": "QGIS", "publisher": "Proyecto QGIS", "url": "https://qgis.org/", "use": "Sistemas de información geográfica gratuitos"}]'::jsonb, null),
  ('ciencia-politica', 'Ciencia Política', 'Ciencias sociales', '#283593', 'Analiza el poder y el Estado: teoría política, instituciones, sistema político colombiano, elecciones, políticas públicas y participación.', 89900, 5, '[{"title": "Constitución Política de Colombia de 1991", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/constitucion_politica_1991.html", "use": "Sistema político colombiano"}, {"title": "Registraduría Nacional del Estado Civil", "publisher": "Organización electoral", "url": "https://www.registraduria.gov.co/", "use": "Elecciones y participación"}]'::jsonb, null),
  ('economia', 'Economía', 'Ciencias sociales', '#2E7D32', 'Entiende cómo funcionan los mercados, el dinero y el crecimiento: micro y macroeconomía, economía colombiana, finanzas y políticas económicas.', 89900, 5, '[{"title": "Banco de la República", "publisher": "Banco central de Colombia", "url": "https://www.banrep.gov.co/es", "use": "Política monetaria y datos económicos"}, {"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "PIB, inflación y empleo"}]'::jsonb, null),
  ('relaciones-internacionales', 'Relaciones Internacionales', 'Ciencias sociales', '#1565C0', 'Comprende el sistema internacional: teorías, diplomacia, organismos multilaterales, derecho internacional, comercio y la política exterior de Colombia.', 89900, 5, '[{"title": "Cancillería de Colombia", "publisher": "Ministerio de Relaciones Exteriores", "url": "https://www.cancilleria.gov.co/", "use": "Política exterior colombiana"}, {"title": "Naciones Unidas", "publisher": "ONU", "url": "https://www.un.org/es/", "use": "Sistema internacional y multilateralismo"}]'::jsonb, null),
  ('trabajo-social', 'Trabajo Social', 'Ciencias sociales', '#EF6C00', 'Aprende a acompañar personas, familias y comunidades: intervención social, derechos, políticas sociales, gestión de proyectos y ética profesional.', 89900, 5, '[{"title": "Consejo Nacional de Trabajo Social", "publisher": "Colombia", "url": "https://www.consejonacionaldetrabajosocial.org.co/", "use": "Ejercicio profesional y ética"}, {"title": "Instituto Colombiano de Bienestar Familiar", "publisher": "ICBF", "url": "https://www.icbf.gov.co/", "use": "Protección de niños y familias"}]'::jsonb, null),
  ('demografia', 'Demografía', 'Ciencias sociales', '#00838F', 'Estudia la población: fecundidad, mortalidad, migración, censos, proyecciones y su uso en la planeación, con datos reales de Colombia.', 89900, 5, '[{"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "Censos y estadísticas vitales"}, {"title": "Proyecciones demográficas", "publisher": "CEPAL – CELADE", "url": "https://www.cepal.org/es/subtemas/proyecciones-demograficas", "use": "Población de América Latina"}, {"title": "UNFPA Colombia", "publisher": "Fondo de Población de las Naciones Unidas", "url": "https://colombia.unfpa.org/es", "use": "Población y desarrollo"}]'::jsonb, null),
  ('ciencias-de-la-comunicacion', 'Ciencias de la Comunicación', 'Comunicación', '#D81B60', 'Comunicación, periodismo y medios: teorías, redacción, comunicación organizacional, digital y audiovisual, ética y derecho a la información.', 89900, 5, '[{"title": "Fundación para la Libertad de Prensa", "publisher": "FLIP", "url": "https://flip.org.co/", "use": "Libertad de expresión y periodismo en Colombia"}, {"title": "Ministerio TIC", "publisher": "MinTIC", "url": "https://www.mintic.gov.co/portal/inicio/", "use": "Medios, TIC y comunicaciones"}]'::jsonb, null),
  ('diseno-industrial', 'Diseño Industrial', 'Arte y diseño', '#F4511E', 'Diseña productos útiles y sostenibles: proceso de diseño, ergonomía, materiales, procesos de fabricación, modelado 3D y prototipado.', 89900, 5, '[{"title": "Artesanías de Colombia", "publisher": "Gobierno de Colombia", "url": "https://artesaniasdecolombia.com.co/", "use": "Diseño con comunidades artesanas"}, {"title": "Blender", "publisher": "Blender Foundation", "url": "https://www.blender.org/", "use": "Modelado 3D gratuito"}]'::jsonb, null),
  ('diseno-de-interiores', 'Diseño de Interiores', 'Arte y diseño', '#A1887F', 'Transforma espacios: distribución, iluminación, color, materiales, mobiliario, normativa y proyectos residenciales, comerciales y de hospitalidad.', 89900, 5, '[{"title": "Ministerio de Vivienda, Ciudad y Territorio", "publisher": "Gobierno de Colombia", "url": "https://www.minvivienda.gov.co/", "use": "Normas de vivienda y construcción"}, {"title": "Artesanías de Colombia", "publisher": "Gobierno de Colombia", "url": "https://artesaniasdecolombia.com.co/", "use": "Objetos y materiales artesanales"}]'::jsonb, null),
  ('diseno-de-modas', 'Diseño de Modas', 'Arte y diseño', '#EC407A', 'Crea colecciones: historia de la moda, ilustración, patronaje, confección, textiles, moda sostenible y negocio de la moda en Colombia.', 89900, 5, '[{"title": "Inexmoda", "publisher": "Instituto para la Exportación y la Moda", "url": "https://www.inexmoda.org.co/", "use": "Industria de la moda en Colombia"}, {"title": "Fashion Revolution", "publisher": "Fashion Revolution", "url": "https://www.fashionrevolution.org/", "use": "Moda sostenible y transparente"}]'::jsonb, null),
  ('artes-plasticas', 'Artes Plásticas', 'Arte y diseño', '#C62828', 'Expresión con las manos y la materia: dibujo, pintura, escultura, grabado y cerámica, historia del arte y creación de obra propia.', 89900, 5, '[{"title": "Museo Nacional de Colombia", "publisher": "Ministerio de las Culturas", "url": "https://www.museonacional.gov.co/", "use": "Colecciones de arte e historia"}, {"title": "Banrepcultural", "publisher": "Banco de la República", "url": "https://www.banrepcultural.org/", "use": "Colección de arte y Red de Bibliotecas"}]'::jsonb, null),
  ('artes-visuales', 'Artes Visuales', 'Arte y diseño', '#7E57C2', 'Crea con la imagen en todas sus formas: cultura visual, imagen digital, video arte, arte interactivo, curaduría y nuevos medios.', 89900, 5, '[{"title": "Museo de Arte Moderno de Bogotá", "publisher": "MAMBO", "url": "https://www.mambogota.com/", "use": "Arte moderno y contemporáneo"}, {"title": "Banrepcultural", "publisher": "Banco de la República", "url": "https://www.banrepcultural.org/", "use": "Exposiciones y colección de arte"}]'::jsonb, null),
  ('musica', 'Música', 'Arte y diseño', '#E53935', 'Aprende música desde cero: teoría, lectura, ritmo, armonía, canto e instrumento, músicas colombianas, producción musical y carrera artística.', 89900, 5, '[{"title": "Ministerio de las Culturas, las Artes y los Saberes", "publisher": "Gobierno de Colombia", "url": "https://www.mincultura.gov.co/", "use": "Plan Nacional de Música y estímulos"}, {"title": "SAYCO", "publisher": "Sociedad de Autores y Compositores de Colombia", "url": "https://www.sayco.org/", "use": "Derechos de autor musicales"}]'::jsonb, null),
  ('teatro', 'Teatro', 'Arte y diseño', '#8E24AA', 'Del cuerpo y la voz al montaje: actuación, dramaturgia, dirección, escenografía, historia del teatro y teatro colombiano.', 89900, 5, '[{"title": "Teatro Mayor Julio Mario Santo Domingo", "publisher": "Bogotá", "url": "https://www.teatromayor.org/", "use": "Programación de artes escénicas"}, {"title": "Ministerio de las Culturas, las Artes y los Saberes", "publisher": "Gobierno de Colombia", "url": "https://www.mincultura.gov.co/", "use": "Estímulos para las artes escénicas"}]'::jsonb, null),
  ('cine-y-produccion-audiovisual', 'Cine y Producción Audiovisual', 'Arte y diseño', '#424242', 'Haz cine de principio a fin: guion, dirección, cámara, iluminación, sonido, edición, producción, distribución y cine colombiano.', 89900, 5, '[{"title": "Proimágenes Colombia", "publisher": "Fondo para el Desarrollo Cinematográfico", "url": "https://www.proimagenescolombia.com/", "use": "Convocatorias y datos del cine colombiano"}, {"title": "FICCI – Festival Internacional de Cine de Cartagena", "publisher": "FICCI", "url": "https://ficcifestival.com/", "use": "Festival de cine"}]'::jsonb, null),
  ('fotografia', 'Fotografía', 'Arte y diseño', '#546E7A', 'Domina la cámara y la luz: exposición, composición, retrato, paisaje, producto, edición, fotografía documental y negocio fotográfico.', 89900, 5, '[{"title": "World Press Photo", "publisher": "World Press Photo Foundation", "url": "https://www.worldpressphoto.org/", "use": "Fotoperiodismo y fotografía documental"}, {"title": "Biblioteca Nacional de Colombia", "publisher": "Ministerio de las Culturas", "url": "https://bibliotecanacional.gov.co/", "use": "Archivo fotográfico histórico"}]'::jsonb, null),
  ('animacion-digital', 'Animación Digital', 'Arte y diseño', '#00ACC1', 'Da vida a personajes y mundos: principios de animación, 2D, 3D, modelado, rigging, motion graphics, videojuegos y producción animada.', 89900, 5, '[{"title": "Pixar en una caja", "publisher": "Khan Academy y Pixar", "url": "https://es.khanacademy.org/computing/pixar", "use": "Cómo se hace la animación"}, {"title": "Blender", "publisher": "Blender Foundation", "url": "https://www.blender.org/", "use": "Animación 3D gratuita"}]'::jsonb, null),
  ('escritura-creativa', 'Escritura Creativa', 'Arte y diseño', '#5D4037', 'Encuentra tu voz: cuento, novela, poesía, crónica, guion, edición, publicación y la vida del escritor, con referentes latinoamericanos.', 89900, 5, '[{"title": "Diccionario de la lengua española", "publisher": "RAE – ASALE", "url": "https://dle.rae.es/", "use": "Léxico y norma"}, {"title": "Biblioteca Nacional de Colombia", "publisher": "Ministerio de las Culturas", "url": "https://bibliotecanacional.gov.co/", "use": "Literatura colombiana digitalizada"}]'::jsonb, null),
  ('arquitectura', 'Arquitectura', 'Arte y diseño', '#455A64', 'Proyecta espacios para habitar: historia, dibujo, diseño arquitectónico, estructuras, construcción, urbanismo, sostenibilidad y BIM.', 89900, 5, '[{"title": "Sociedad Colombiana de Arquitectos", "publisher": "SCA", "url": "https://sociedadcolombianadearquitectos.org/", "use": "Gremio, concursos y noticias de arquitectura"}, {"title": "Ministerio de Vivienda, Ciudad y Territorio", "publisher": "Gobierno de Colombia", "url": "https://www.minvivienda.gov.co/", "use": "Normas urbanas y de construcción"}]'::jsonb, null),
  ('publicidad', 'Publicidad', 'Comunicación', '#FB8C00', 'Crea campañas que conectan: estrategia, creatividad, redacción publicitaria, dirección de arte, medios, publicidad digital y marcas.', 89900, 5, '[{"title": "Ley 1480 de 2011 (Estatuto del Consumidor)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1480_2011.html", "use": "Publicidad engañosa y derechos del consumidor"}, {"title": "Skillshop", "publisher": "Google", "url": "https://skillshop.withgoogle.com/", "use": "Publicidad digital y certificaciones"}]'::jsonb, null)
